            rw.Single(ref this.u19);
            rw.Single(ref this.u20);
            rw.Single(ref this.u21);
            rw.Single(ref this.u22);
            rw.Single(ref this.u23);
            rw.Single(ref this.u24);
        }

        public virtual void Read(GbxReader r, int v = 0)
        {
            using var rw = new GbxReaderWriter(r);
            ReadWrite(rw, v);
        }

        public virtual void Write(GbxWriter w, int v = 0)
        {
            using var rw = new GbxReaderWriter(w);
            ReadWrite(rw, v);
        }
    }

    internal override IChunk? NewChunk(uint chunkId) => chunkId switch
    {
        0x0316F000 => new Chunk0316F000(),
        0x0316F001 => new Chunk0316F001(),
        0x0316F002 => new Chunk0316F002(),
        0x0316F003 => new Chunk0316F003(),
        0x0316F004 => new Chunk0316F004(),
        _ => base.NewChunk(chunkId),
    };
}
